// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner, bool callerIsOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);
        if (callerIsOwner) {
            vm.prank(c.owner());
            c.transferOwnership(caller);
        }
        address ownerBefore = c.owner();
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            if (caller != ownerBefore) {
                assertTrue(c.owner() == ownerBefore);
            }
        } catch {
            assertTrue(ownerBefore == c.owner());
        }
    }
}
